def preorder_traversal(inorder, postorder):
    inorder_dict = {char: i for i, char in enumerate(inorder)}
    postorder_dict = {char: i for i, char in enumerate(postorder)}
    inorder_list = list(inorder_dict.keys())
    postorder_list = list(postorder_dict.keys())
    def build_tree(inorder_list, postorder_list):
        if not inorder_list or not postorder_list:
            return None
        root = postorder_list[-1]
        root_index = inorder_dict[root]
        left_inorder = inorder_list[:root_index]
        right_inorder = inorder_list[root_index+1:]
        left_postorder = postorder_list[:len(left_inorder)]
        right_postorder = postorder_list[len(left_inorder):-1]
        root.left = build_tree(left_inorder, left_postorder)
        root.right = build_tree(right_inorder, right_postorder)
        return root
    return "".join(build_tree(inorder_list, postorder_list))

